from __future__ import annotations

import httpx


def make_http_client(*, timeout: float = 30.0, follow_redirects: bool = True) -> httpx.Client:
    """HTTP client that ignores system proxy env (avoids broken SOCKS proxy crashes)."""
    return httpx.Client(timeout=timeout, follow_redirects=follow_redirects, trust_env=False)

from __future__ import annotations

import json
import re
from importlib.resources import files
from pathlib import Path


def _default_corpus() -> list[dict[str, str]]:
    return [
        {
            "tags": "学术 引言 结构 thesis",
            "text": (
                "强引言应在一段内交代研究背景、核心问题与本文贡献。"
                "避免空泛套话，用具体现象或数据切入；末句明确论文主张（thesis）。"
            ),
        },
        {
            "tags": "引用 段内 citation in-text",
            "text": (
                "每个论证段落至少一处段内引用，且同一段落避免重复同一文献。"
                "引用应支撑具体论断，而非装饰性堆砌；优先近五年高相关研究。"
            ),
        },
        {
            "tags": "去AI 自然 学术风格",
            "text": (
                "去AI化写作：减少“综上所述”“值得注意的是”等模板句；"
                "句式长短交替；用领域术语与具体案例替代笼统形容词；保持克制客观语气。"
            ),
        },
        {
            "tags": "方法 证据 分析",
            "text": (
                "分析段遵循“主张—证据—解释”：先给出判断，再引用文献或数据，"
                "最后说明证据如何支持主张并回应可能反驳。"
            ),
        },
    ]


def load_corpus() -> list[dict[str, str]]:
    try:
        path = files("academic_agent").joinpath("data", "writing_corpus.json")
        if path.is_file():
            return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        pass
    return _default_corpus()


def retrieve_snippets(topic: str, *, limit: int = 3) -> str:
    """Lightweight keyword retrieval — no embedding dependency."""
    corpus = load_corpus()
    words = set(re.findall(r"[\u4e00-\u9fff]{2,}|[A-Za-z]{3,}", topic.lower()))
    scored: list[tuple[int, str]] = []
    for item in corpus:
        hay = f"{item.get('tags', '')} {item.get('text', '')}".lower()
        score = sum(1 for w in words if w in hay)
        scored.append((score, item.get("text", "")))
    scored.sort(key=lambda x: x[0], reverse=True)
    picked = [t for s, t in scored if t][:limit]
    if not picked:
        picked = [c.get("text", "") for c in corpus[:limit]]
    return "\n".join(f"- {p}" for p in picked if p)

from __future__ import annotations

import json
from collections.abc import Iterable
from typing import Any

import httpx
from tenacity import retry, stop_after_attempt, wait_exponential

from academic_agent.config import Settings, get_settings
from academic_agent.http_utils import make_http_client


class OpenAICompatibleClient:
    """Small chat-completions client for OpenAI-compatible endpoints."""

    def __init__(self, settings: Settings | None = None) -> None:
        self.settings = settings or get_settings()
        base = self.settings.openai_base_url.rstrip("/")
        if base.endswith("/chat/completions"):
            base = base[: -len("/chat/completions")].rstrip("/")
        if not base.endswith("/v1"):
            base = f"{base}/v1"
        self.base_url = base
        self.model = self.settings.openai_model

    @retry(wait=wait_exponential(multiplier=1, min=1, max=12), stop=stop_after_attempt(3))
    def chat(
        self,
        messages: list[dict[str, str]],
        *,
        temperature: float = 0.2,
        max_tokens: int | None = None,
        response_format: dict[str, Any] | None = None,
    ) -> str:
        if not self.settings.openai_api_key:
            raise RuntimeError("缺少 API Key。请先在页面登录。")

        payload: dict[str, Any] = {
            "model": self.model,
            "messages": messages,
            "temperature": temperature,
        }
        if max_tokens is not None:
            payload["max_tokens"] = max_tokens
        if response_format is not None:
            payload["response_format"] = response_format

        headers = {
            "Authorization": f"Bearer {self.settings.openai_api_key}",
            "Content-Type": "application/json",
        }
        data = self._post_chat(payload, headers)
        content = self._extract_content(data)
        if content:
            return content

        # Reasoning models may exhaust budget — retry with larger max_tokens once.
        if max_tokens is not None:
            payload_retry = {**payload, "max_tokens": min(max_tokens * 3, 16000)}
            data = self._post_chat(payload_retry, headers)
            content = self._extract_content(data)
            if content:
                return content

        raise RuntimeError(
            "模型返回为空。请换用 deepseek-chat，或在设置中改用 deepseek-v4-flash。"
        )

    def _post_chat(self, payload: dict[str, Any], headers: dict[str, str]) -> dict[str, Any]:
        try:
            with make_http_client(timeout=self.settings.openai_timeout_seconds) as client:
                response = client.post(f"{self.base_url}/chat/completions", headers=headers, json=payload)
                try:
                    response.raise_for_status()
                except httpx.HTTPStatusError as exc:
                    detail = exc.response.text[:800] if exc.response is not None else str(exc)
                    code = exc.response.status_code if exc.response is not None else "?"
                    raise RuntimeError(f"模型 API 请求失败 ({code}): {detail}") from exc
                return response.json()
        except httpx.HTTPError as exc:
            raise RuntimeError(f"网络请求失败: {exc}") from exc

    @staticmethod
    def _extract_content(data: dict[str, Any]) -> str:
        try:
            message = data["choices"][0]["message"]
            return (message.get("content") or "").strip()
        except (KeyError, IndexError, TypeError):
            return ""

    def json_chat(self, messages: list[dict[str, str]], *, temperature: float = 0.1) -> dict[str, Any]:
        content = self.chat(
            messages,
            temperature=temperature,
            response_format={"type": "json_object"},
        )
        try:
            return json.loads(content)
        except json.JSONDecodeError:
            start = content.find("{")
            end = content.rfind("}")
            if start >= 0 and end > start:
                return json.loads(content[start : end + 1])
            raise


def compact_sources(papers: Iterable[Any], limit: int = 12, *, numbered: bool = True) -> str:
    lines: list[str] = []
    for index, paper in enumerate(list(papers)[:limit], start=1):
        authors = ", ".join(paper.authors[:4]) if paper.authors else "Unknown authors"
        year = paper.year or "n.d."
        doi = f" DOI: {paper.doi}." if paper.doi else ""
        abstract = f" Abstract: {paper.abstract[:700]}" if paper.abstract else ""
        key = getattr(paper, "citation_key", None) or f"ref{index}"
        prefix = f"[{index}]" if numbered else "-"
        from academic_agent.scholar_quality import paper_link

        plink = paper_link(paper)
        lines.append(
            f"{prefix} key={key} | {paper.title} ({year}). {authors}.{doi}{abstract} Link: {plink}"
        )
    return "\n".join(lines)

from __future__ import annotations

from academic_agent.config import Settings, get_settings
from academic_agent.llm import OpenAICompatibleClient
from starlette.requests import Request

DEEPSEEK_DEFAULTS = {
    "base_url": "https://api.deepseek.com/v1",
    "model": "deepseek-chat",
}


def normalize_base_url(url: str) -> str:
    """Ensure OpenAI-compatible base URL ends with /v1."""
    cleaned = (url or "").strip().rstrip("/")
    if not cleaned:
        return DEEPSEEK_DEFAULTS["base_url"]
    if cleaned.endswith("/v1"):
        return cleaned
    if cleaned.endswith("/chat/completions"):
        return cleaned[: -len("/chat/completions")].rstrip("/")
    return f"{cleaned}/v1"


def tavily_key_from_request(request: Request) -> str:
    return (request.headers.get("x-tavily-key") or "").strip()


def settings_from_request(request: Request) -> Settings:
    """Use per-request LLM headers only — never fall back to server .env API key."""
    base = get_settings()
    api_key = (request.headers.get("x-api-key") or "").strip()
    base_url = normalize_base_url((request.headers.get("x-base-url") or "").strip() or base.openai_base_url)
    model = (request.headers.get("x-model") or "").strip() or base.openai_model
    return base.model_copy(
        update={
            "openai_api_key": api_key,
            "openai_base_url": base_url,
            "openai_model": model,
        }
    )


def client_from_settings(settings: Settings) -> OpenAICompatibleClient:
    normalized = settings.model_copy(update={"openai_base_url": normalize_base_url(settings.openai_base_url)})
    return OpenAICompatibleClient(settings=normalized)


def client_from_request(request: Request) -> OpenAICompatibleClient:
    return client_from_settings(settings_from_request(request))

from __future__ import annotations

import re
from urllib.parse import quote_plus

from academic_agent.models import Paper, SourceName

_CJK = re.compile(r"[\u4e00-\u9fff\u3040-\u30ff\uac00-\ud7af]")
_LATIN_RATIO = re.compile(r"[A-Za-z]")


def is_english_scholarly(paper: Paper) -> bool:
    title = paper.title or ""
    if _CJK.search(title):
        return False
    if _CJK.search(paper.abstract or ""):
        return False
    letters = len(_LATIN_RATIO.findall(title))
    if letters < max(8, len(title) * 0.45):
        return False
    if not paper.abstract or len(paper.abstract.strip()) < 60:
        return False
    return True


def paper_link(paper: Paper) -> str:
    if paper.doi:
        return f"https://doi.org/{paper.doi}"
    if paper.url:
        return str(paper.url)
    if paper.arxiv_id:
        return f"https://arxiv.org/abs/{paper.arxiv_id}"
    return scholar_url(paper)


def scholar_url(paper: Paper) -> str:
    q = quote_plus(paper.title)
    if paper.authors:
        q = quote_plus(f"{paper.title} {paper.authors[0]}")
    return f"https://scholar.google.com/scholar?hl=en&q={q}"


def quality_rank(paper: Paper) -> int:
    score = 0
    if paper.source == SourceName.SEMANTIC_SCHOLAR:
        score += 12
    if paper.source == SourceName.OPENALEX:
        score += 8
    if paper.doi:
        score += 10
    if paper.abstract:
        score += 6
    cites = paper.citation_count or 0
    score += min(cites, 500) // 5
    if paper.venue:
        score += 3
    return score


def is_scholarly_source(paper: Paper) -> bool:
    return paper.source in {
        SourceName.SEMANTIC_SCHOLAR,
        SourceName.OPENALEX,
        SourceName.CROSSREF,
        SourceName.ARXIV,
    }


def filter_scholar_quality(papers: list[Paper], *, min_citations: int = 5) -> list[Paper]:
    filtered: list[Paper] = []
    for p in papers:
        if not is_scholarly_source(p):
            continue
        if not is_english_scholarly(p):
            continue
        cites = p.citation_count or 0
        if cites < min_citations and p.source not in {SourceName.ARXIV, SourceName.SEMANTIC_SCHOLAR}:
            continue
        if p.source == SourceName.CROSSREF and cites < 3 and not p.doi:
            continue
        filtered.append(p)
    filtered.sort(key=quality_rank, reverse=True)
    return filtered

from __future__ import annotations

import re

_CJK = re.compile(r"[\u4e00-\u9fff\u3040-\u30ff\uac00-\ud7af]")


def topic_needs_english_queries(topic: str) -> bool:
    return bool(_CJK.search(topic))


def english_scholar_queries(topic: str, *, llm=None) -> list[str]:
    """Build English search phrases for scholarly APIs (GS has no public API)."""
    topic = topic.strip()
    if not topic:
        return []
    if not topic_needs_english_queries(topic):
        return _dedupe_queries([topic])

    if llm is not None:
        try:
            raw = llm.chat(
                [
                    {
                        "role": "system",
                        "content": (
                            "Translate academic topics into 3 concise English Google Scholar search queries. "
                            "Return one query per line, no numbering, no Chinese."
                        ),
                    },
                    {"role": "user", "content": f"Topic: {topic}"},
                ],
                temperature=0.1,
                max_tokens=180,
            )
            lines = [ln.strip(" -•\t") for ln in raw.splitlines() if ln.strip()]
            cleaned = [ln for ln in lines if ln and not _CJK.search(ln)]
            if cleaned:
                return _dedupe_queries(cleaned[:4])
        except Exception:
            pass

    return _dedupe_queries([topic, f"{topic} systematic review", f"{topic} empirical study"])


def _dedupe_queries(queries: list[str]) -> list[str]:
    seen: set[str] = set()
    out: list[str] = []
    for q in queries:
        key = re.sub(r"\W+", " ", q.lower()).strip()
        if not key or key in seen:
            continue
        seen.add(key)
        out.append(q.strip())
    return out

from __future__ import annotations

import re
import xml.etree.ElementTree as ET
from collections.abc import Iterable
from collections.abc import Callable
from urllib.parse import quote_plus

import httpx

from academic_agent.config import Settings, get_settings
from academic_agent.http_utils import make_http_client
from academic_agent.models import Paper, SourceName
from academic_agent.scholar_quality import filter_scholar_quality, is_scholarly_source
from academic_agent.scholar_search import search_scholar_multi, search_scholar_primary
from academic_agent.tavily_search import search_tavily


def _clean_text(value: str | None) -> str | None:
    if not value:
        return None
    return re.sub(r"\s+", " ", value).strip()


def _author_names(items: Iterable[dict]) -> list[str]:
    names: list[str] = []
    for item in items:
        name = item.get("display_name") or item.get("name")
        if name:
            names.append(str(name))
    return names


class AcademicSearcher:
    def __init__(self, settings: Settings | None = None) -> None:
        self.settings = settings or get_settings()

    def search(
        self,
        query: str,
        *,
        limit: int = 10,
        tavily_key: str = "",
        web_search: bool = True,
        extra_queries: list[str] | None = None,
    ) -> list[Paper]:
        queries = [query.strip()]
        if extra_queries:
            queries.extend(q.strip() for q in extra_queries if q.strip())
        results: list[Paper] = (
            search_scholar_multi(queries, limit=max(limit, 15))
            if len(queries) > 1
            else list(search_scholar_primary(query, limit=max(limit, 15)))
        )
        if len(results) < limit:
            per_source = max(4, min(limit, 15))
            with make_http_client(timeout=30.0) as client:
                for fetcher in (self._semantic_scholar, self._openalex):
                    results.extend(self._safe_fetch(fetcher, client, query, per_source))
        results = dedupe_papers(results)
        results = [p for p in results if is_scholarly_source(p)]
        results = filter_scholar_quality(results, min_citations=3)
        if len(results) < limit:
            relaxed = filter_scholar_quality(dedupe_papers(results), min_citations=1)
            results = relaxed[:limit]
        if web_search and tavily_key and len(results) < max(4, limit // 3):
            # Tavily only fills gaps; never used as primary citations.
            tavily_hits = search_tavily(query, api_key=tavily_key, limit=3)
            results = dedupe_papers(results + tavily_hits)
            results = [p for p in results if is_scholarly_source(p)] or results[:limit]
        return results[:limit]

    def by_doi(self, doi: str) -> Paper | None:
        doi = doi.strip().removeprefix("https://doi.org/")
        with make_http_client(timeout=30.0) as client:
            for fetcher in (self._crossref_doi, self._openalex_doi):
                try:
                    paper = fetcher(client, doi)
                except httpx.HTTPError:
                    paper = None
                if paper:
                    return paper
        return None

    def by_arxiv_id(self, arxiv_id: str) -> Paper | None:
        arxiv_id = arxiv_id.strip().removeprefix("arXiv:")
        url = f"https://export.arxiv.org/api/query?id_list={quote_plus(arxiv_id)}"
        with make_http_client(timeout=30.0) as client:
            response = client.get(url)
            if response.status_code >= 400:
                return None
            papers = self._parse_arxiv(response.text)
        return papers[0] if papers else None

    def _openalex(self, client: httpx.Client, query: str, limit: int) -> list[Paper]:
        response = client.get(
            "https://api.openalex.org/works",
            params={
                "search": query,
                "per-page": limit,
                "filter": "language:en,cited_by_count:>5,type:article",
                "sort": "cited_by_count:desc",
            },
        )
        if response.status_code >= 400:
            return []
        return [self._openalex_work(item) for item in response.json().get("results", [])]

    @staticmethod
    def _safe_fetch(
        fetcher: Callable[[httpx.Client, str, int], list[Paper]],
        client: httpx.Client,
        query: str,
        limit: int,
    ) -> list[Paper]:
        try:
            return fetcher(client, query, limit)
        except (httpx.HTTPError, ET.ParseError):
            return []

    def _openalex_doi(self, client: httpx.Client, doi: str) -> Paper | None:
        response = client.get(f"https://api.openalex.org/works/https://doi.org/{doi}")
        if response.status_code >= 400:
            return None
        return self._openalex_work(response.json())

    def _openalex_work(self, item: dict) -> Paper:
        authorships = item.get("authorships") or []
        authors = [a.get("author", {}).get("display_name") for a in authorships]
        abstract = inverted_index_to_text(item.get("abstract_inverted_index"))
        primary_location = item.get("primary_location") or {}
        source = primary_location.get("source") or {}
        return Paper(
            title=_clean_text(item.get("title")) or "Untitled",
            authors=[a for a in authors if a],
            year=item.get("publication_year"),
            abstract=abstract,
            doi=(item.get("doi") or "").removeprefix("https://doi.org/") or None,
            url=item.get("id") or item.get("doi"),
            venue=source.get("display_name"),
            citation_count=item.get("cited_by_count"),
            source=SourceName.OPENALEX,
            source_id=item.get("id"),
            raw=item,
        )

    def _semantic_scholar(self, client: httpx.Client, query: str, limit: int) -> list[Paper]:
        headers = {}
        if self.settings.semantic_scholar_api_key:
            headers["x-api-key"] = self.settings.semantic_scholar_api_key
        response = client.get(
            "https://api.semanticscholar.org/graph/v1/paper/search",
            params={
                "query": query,
                "limit": limit,
                "fields": "title,authors,year,abstract,venue,citationCount,externalIds,url",
            },
            headers=headers,
        )
        if response.status_code >= 400:
            return []
        papers: list[Paper] = []
        for item in response.json().get("data", []):
            external = item.get("externalIds") or {}
            papers.append(
                Paper(
                    title=_clean_text(item.get("title")) or "Untitled",
                    authors=_author_names(item.get("authors") or []),
                    year=item.get("year"),
                    abstract=_clean_text(item.get("abstract")),
                    doi=external.get("DOI"),
                    arxiv_id=external.get("ArXiv"),
                    url=item.get("url"),
                    venue=item.get("venue"),
                    citation_count=item.get("citationCount"),
                    source=SourceName.SEMANTIC_SCHOLAR,
                    source_id=item.get("paperId"),
                    raw=item,
                )
            )
        return papers

    def _crossref(self, client: httpx.Client, query: str, limit: int) -> list[Paper]:
        response = client.get("https://api.crossref.org/works", params={"query": query, "rows": limit})
        if response.status_code >= 400:
            return []
        return [self._crossref_item(item) for item in response.json().get("message", {}).get("items", [])]

    def _crossref_doi(self, client: httpx.Client, doi: str) -> Paper | None:
        response = client.get(f"https://api.crossref.org/works/{quote_plus(doi)}")
        if response.status_code >= 400:
            return None
        item = response.json().get("message")
        return self._crossref_item(item) if item else None

    def _crossref_item(self, item: dict) -> Paper:
        authors = []
        for author in item.get("author") or []:
            given = author.get("given", "")
            family = author.get("family", "")
            name = " ".join(part for part in [given, family] if part).strip()
            if name:
                authors.append(name)
        year = None
        date_parts = (item.get("published-print") or item.get("published-online") or item.get("created") or {}).get(
            "date-parts"
        )
        if date_parts and date_parts[0]:
            year = date_parts[0][0]
        titles = item.get("title") or []
        containers = item.get("container-title") or []
        abstracts = item.get("abstract")
        return Paper(
            title=_clean_text(titles[0] if titles else None) or "Untitled",
            authors=authors,
            year=year,
            abstract=_clean_text(strip_tags(abstracts)),
            doi=item.get("DOI"),
            url=item.get("URL"),
            venue=containers[0] if containers else None,
            citation_count=item.get("is-referenced-by-count"),
            source=SourceName.CROSSREF,
            source_id=item.get("DOI"),
            raw=item,
        )

    def _arxiv(self, client: httpx.Client, query: str, limit: int) -> list[Paper]:
        url = (
            "https://export.arxiv.org/api/query"
            f"?search_query=all:{quote_plus(query)}&start=0&max_results={limit}&sortBy=relevance"
        )
        response = client.get(url)
        if response.status_code >= 400:
            return []
        return self._parse_arxiv(response.text)

    @staticmethod
    def _parse_arxiv(xml_text: str) -> list[Paper]:
        ns = {"a": "http://www.w3.org/2005/Atom"}
        root = ET.fromstring(xml_text)
        papers: list[Paper] = []
        for entry in root.findall("a:entry", ns):
            entry_id = entry.findtext("a:id", default="", namespaces=ns)
            arxiv_id = entry_id.rsplit("/", 1)[-1] if entry_id else None
            authors = [node.findtext("a:name", default="", namespaces=ns) for node in entry.findall("a:author", ns)]
            published = entry.findtext("a:published", default="", namespaces=ns)
            doi_node = entry.find("{http://arxiv.org/schemas/atom}doi")
            doi = doi_node.text if doi_node is not None else None
            papers.append(
                Paper(
                    title=_clean_text(entry.findtext("a:title", default="", namespaces=ns)) or "Untitled",
                    authors=[a for a in authors if a],
                    year=int(published[:4]) if published[:4].isdigit() else None,
                    abstract=_clean_text(entry.findtext("a:summary", default="", namespaces=ns)),
                    doi=doi,
                    arxiv_id=arxiv_id,
                    url=entry_id,
                    source=SourceName.ARXIV,
                    source_id=arxiv_id,
                    raw={},
                )
            )
        return papers


def strip_tags(text: str | None) -> str | None:
    if not text:
        return None
    return re.sub(r"<[^>]+>", " ", text)


def inverted_index_to_text(index: dict[str, list[int]] | None) -> str | None:
    if not index:
        return None
    words: list[str | None] = [None] * (max(pos for positions in index.values() for pos in positions) + 1)
    for word, positions in index.items():
        for pos in positions:
            words[pos] = word
    return _clean_text(" ".join(word or "" for word in words))


def dedupe_papers(papers: list[Paper]) -> list[Paper]:
    index_by_key: dict[str, int] = {}
    unique: list[Paper] = []
    for paper in papers:
        key = paper.doi.lower() if paper.doi else normalize_title(paper.title)
        if key in index_by_key:
            current_index = index_by_key[key]
            if paper_quality_score(paper) > paper_quality_score(unique[current_index]):
                unique[current_index] = paper
            continue
        index_by_key[key] = len(unique)
        unique.append(paper)
    return unique


def paper_quality_score(paper: Paper) -> int:
    return (
        int(bool(paper.doi)) * 4
        + int(bool(paper.arxiv_id)) * 3
        + int(bool(paper.abstract)) * 2
        + int(bool(paper.url))
        + min(paper.citation_count or 0, 1000) // 100
    )


def normalize_title(title: str) -> str:
    return re.sub(r"\W+", "", title.lower())

/* Joeku — projects · modal params · split doc stream (no ES module — avoids load failures) */

function renderMarkdown(md) {
  if (!md) return "";
  const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const inline = (text) =>
    text
      .replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>')
      .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
      .replace(/\*(.+?)\*/g, "<em>$1</em>")
      .replace(/`([^`]+)`/g, "<code>$1</code>");
  const lines = md.split(/\r?\n/);
  const out = [];
  let inP = false;
  const closeP = () => {
    if (inP) {
      out.push("</p>");
      inP = false;
    }
  };
  for (const raw of lines) {
    const line = raw.trimEnd();
    if (!line.trim()) {
      closeP();
      continue;
    }
    if (line.startsWith("# ")) {
      closeP();
      out.push(`<h1>${inline(esc(line.slice(2)))}</h1>`);
      continue;
    }
    if (line.startsWith("## ")) {
      closeP();
      out.push(`<h2>${inline(esc(line.slice(3)))}</h2>`);
      continue;
    }
    if (line.startsWith("### ")) {
      closeP();
      out.push(`<h3>${inline(esc(line.slice(4)))}</h3>`);
      continue;
    }
    if (line.startsWith("- ") || line.startsWith("* ")) {
      closeP();
      out.push(`<li>${inline(esc(line.slice(2)))}</li>`);
      continue;
    }
    if (!inP) {
      out.push("<p>");
      inP = true;
    } else {
      out.push("<br/>");
    }
    out.push(inline(esc(line)));
  }
  closeP();
  return out.join("");
}

