  }
}

function setDocCollapsed(collapsed) {
  const ws = $("#workspace-generate");
  ws?.classList.toggle("doc-collapsed", collapsed);
  localStorage.setItem(STORAGE.docCollapsed, collapsed ? "1" : "0");
